def transform(grid):
    h, w = len(grid), len(grid[0])
    objects = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[i][j] == color
                             for i in range(r, r + 3)
                             for j in range(c, c + 3)):
                objects.append((r + 1, c + 1, color))

    out = [row[:] for row in grid]
    for r, c, color in objects:
        for j in range(w):
            out[r][j] = color
        for i in range(h):
            out[i][c] = color

    for r, c, _ in objects:
        for rr, cc, _ in objects:
            if r != rr and c != cc:
                out[r][cc] = 0
                out[rr][c] = 0
    return out
